result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/use-ls/src/useLocalStorage.ts", "content": "import { useCallback, useEffect, useState } from "react";

/**
 * Persisted state backed by localStorage.
 *
 * - Reads lazily: localStorage is only touched during the first render,
 *   and only if `key` already exists.
 * - Writes are serialized with JSON.stringify on every set.
 * - Corrupted stored JSON falls back to `initialValue` instead of throwing.
 * - Listens to the window `storage` event so a write in another tab
 *   updates this hook's state.
 */
export function useLocalStorage<T>(
  key: string,
  initialValue: T
): [T, (value: T | ((prev: T) => T)) => void] {
  const [state, setState] = useState<T>(() => {
    try {
      const raw = window.localStorage.getItem(key);
      return raw === null ? initialValue : (JSON.parse(raw) as T);
    } catch {
      return initialValue;
    }
  });

  // Keep in sync when another tab writes to this key.
  useEffect(() => {
    const onStorage = (event: StorageEvent) => {
      if (event.key !== key) return;
      try {
        if (event.newValue === null) {
          // The key was removed elsewhere; reset to the initial value.
          setState(initialValue);
        } else {
          setState(JSON.parse(event.newValue) as T);
        }
      } catch {
        setState(initialValue);
      }
    };

    window.addEventListener("storage", onStorage);
    return () => window.removeEventListener("storage", onStorage);
  }, [key]);

  const setValue = useCallback(
    (value: T | ((prev: T) => T)) => {
      setState((prev) => {
        const next =
          typeof value === "function" ? (value as (p: T) => T)(prev) : value;
        try {
          window.localStorage.setItem(key, JSON.stringify(next));
        } catch {
          // Storage may be full or unavailable; state still updates.
        }
        return next;
      });
    },
    [key]
  );

  return [state, setValue];
}
"})
