result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/use-ls/src/useLocalStorage.test.tsx", "content": "import { act, renderHook } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { useLocalStorage } from "./useLocalStorage";

function dispatchStorage(key: string, newValue: string | null) {
  // jsdom never fires storage events on its own; simulate another tab.
  act(() => {
    window.dispatchEvent(new StorageEvent("storage", { key, newValue }));
  });
}

describe("useLocalStorage", () => {
  it("reads lazily and falls back to the initial value when the key is absent", () => {
    const { result } = renderHook(() =>
      useLocalStorage<string>("absent-key", "fallback")
    );

    expect(result.current[0]).toBe("fallback");
    expect(window.localStorage.getItem("absent-key")).toBeNull();
  });

  it("reads an existing stored value lazily", () => {
    window.localStorage.setItem("existing", JSON.stringify({ n: 42 }));
    const { result } = renderHook(() =>
      useLocalStorage<{ n: number }>("existing", { n: 0 })
    );

    expect(result.current[0]).toEqual({ n: 42 });
  });

  it("persists JSON on set", () => {
    const { result } = renderHook(() =>
      useLocalStorage<{ a: number }>("persisted", { a: 1 })
    );

    act(() => result.current[1]({ a: 7 }));

    expect(result.current[0]).toEqual({ a: 7 });
    expect(window.localStorage.getItem("persisted")).toBe('{"a":7}');
  });

  it("supports functional updates based on the previous value", () => {
    const { result } = renderHook(() => useLocalStorage<number>("counter", 10));

    act(() => result.current[1]((prev) => prev + 5));

    expect(result.current[0]).toBe(15);
    expect(window.localStorage.getItem("counter")).toBe("15");
  });

  it("falls back to the initial value when stored JSON is corrupted", () => {
    window.localStorage.setItem("broken", "{not valid json!!");
    const warn = vi.spyOn(console, "error").mockImplementation(() => {});

    const { result } = renderHook(() =>
      useLocalStorage<number[]>("broken", [1, 2])
    );

    expect(result.current[0]).toEqual([1, 2]);
    warn.mockRestore();
  });

  it("ignores storage events for other keys", () => {
    const { result } = renderHook(() => useLocalStorage<number>("mine", 1));

    dispatchStorage("someone-elses", "999");

    expect(result.current[0]).toBe(1);
  });

  it("updates state when another tab writes to the same key", () => {
    const { result } = renderHook(() => useLocalStorage<number>("shared", 1));
    expect(result.current[0]).toBe(1);

    dispatchStorage("shared", JSON.stringify(99));

    expect(result.current[0]).toBe(99);
  });

  it("resets to the initial value when another tab removes the key", () => {
    window.localStorage.setItem("shared", "5");
    const { result } = renderHook(() => useLocalStorage<number>("shared", 5));
    expect(result.current[0]).toBe(5);

    dispatchStorage("shared", null);

    expect(result.current[0]).toBe(5); // initial value
  });
});
"})
