result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/use-ls/src/test-setup.ts", "content": "import { afterEach } from "vitest";
import { cleanup } from "@testing-library/react";

// Node >= 22 ships an experimental `localStorage` that requires
// --localstorage-file; vitest's global population copies it onto the
// jsdom window, shadowing jsdom's working implementation. Install an
// in-memory Web Storage implementation so `window.localStorage`
// behaves exactly like the spec.
const store = new Map<string, string>();
Object.defineProperty(window, "localStorage", {
  configurable: true,
  value: {
    get length() {
      return store.size;
    },
    key(index: number): string | null {
      return [...store.keys()][index] ?? null;
    },
    getItem(key: string): string | null {
      return store.has(key) ? store.get(key)! : null;
    },
    setItem(key: string, value: string): void {
      store.set(key, String(value));
    },
    removeItem(key: string): void {
      store.delete(key);
    },
    clear(): void {
      store.clear();
    },
  },
});

afterEach(() => {
  cleanup();
  window.localStorage.clear();
});
"})
